# gems a carrier collects before walking to an altar to tribute
BAG_MIN = 20
# round after which carriers tribute whatever they hold
LATE_ROUND = 1500
# fuel left below which optional expensive steps are skipped this turn
FUEL_SAFE = 30000
# fuel left needed for the gems-per-turn camp scoring
SCORE_FUEL = 50000
# fixed turns added to every camp trip (capture timer plus overhead)
