let goals = minus( camp_spawns, resp )

# already standing on a cleared camp spawn: hold so the capture timer keeps running,
# but only for up to 25 idle turns; after that, move on to the next goal
if contains(goals, position()) and turns_idle() < 25:
    end_turn()

# rich camp groups (static), and gem/elk groups as the fallback
keep rich_all = rich_spawns(10)
keep gem_goals_all = union( gem_cluster_tiles(), elk_tiles() )

# rich-target scoring is the costliest part of the turn: skip it when fuel is low
if fuel_remaining() > FUEL_SAFE:
    let team_n = 1 + allies_within(4)
    let rich_target = closest( minus( rich_all, resp ) )
    let gem_target = closest( minus( gem_goals_all, resp ) )
    # teaming gate: alone, only take rich groups after SOLO_ROUND
    let teamed = team_n > 1 or allies_within(6) > 0 or round_number() > SOLO_ROUND
    let rich_ok = exists(rich_target) and teamed and group_threat(rich_target) * group_hp(rich_target) <= health() * CLEAR_POWER * team_n
    if rich_ok and exists(gem_target) and fuel_remaining() > SCORE_FUEL:
        # value-vs-distance: gems per turn of travel and clearing
        let rich_val = group_gems( filter( rich_all, within(0, rich_target) ) ) / ( distance(position(), rich_target) + group_hp(rich_target) / (CLEAR_POWER * team_n) + TRIP_OVERHEAD )
        let gem_val = group_gems( filter( gem_goals_all, within(0, gem_target) ) ) / ( distance(position(), gem_target) + group_hp(gem_target) / (CLEAR_POWER * team_n) + TRIP_OVERHEAD )
        if rich_val >= gem_val:
            claim(rich_target)
            go( rich_target )
        else:
            unclaim()
            go( gem_target )
    elif rich_ok:
        claim(rich_target)
        go( rich_target )
    else:
        unclaim()
        if exists(gem_target):
            go( gem_target )
        else:
            move_towards( closest(goals) )
else:
    unclaim()
    let gem_target_lo = closest( minus( gem_goals_all, resp ) )
    if exists(gem_target_lo):
        go( gem_target_lo )
    else:
        move_towards( closest(goals) )

